package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.LocalDate;
@Entity @Table(name="succession_development_source",uniqueConstraints=@UniqueConstraint(name="uk_succ_dev_source",columnNames={"agency_id","plan_id","source_type","source_id"}))
public class SuccessionDevelopmentSource extends RspAuditedEntity{
 public enum SourceType{APPROVED_IDP_ITEM,COMPLETED_LD_CASE}
 @Column(name="plan_id",nullable=false,length=36)private String planId;@Enumerated(EnumType.STRING)@Column(name="source_type",nullable=false,length=30)private SourceType sourceType;@Column(name="source_id",nullable=false,length=36)private String sourceId;@Column(name="source_parent_id",length=36)private String sourceParentId;@Column(name="source_version",nullable=false)private long sourceVersion;@Column(name="source_fingerprint",nullable=false,length=120)private String sourceFingerprint;@Column(name="source_summary",nullable=false,length=2000)private String sourceSummary;@Column(name="source_date")private LocalDate sourceDate;
 protected SuccessionDevelopmentSource(){}public SuccessionDevelopmentSource(String agency,String plan,SourceType type,String source,String parent,long version,String fingerprint,String summary,LocalDate date){super(agency);planId=requiredText(plan,"planId");sourceType=java.util.Objects.requireNonNull(type);sourceId=requiredText(source,"sourceId");sourceParentId=optionalText(parent);if(version<0)throw new IllegalArgumentException("sourceVersion cannot be negative");sourceVersion=version;sourceFingerprint=requiredText(fingerprint,"sourceFingerprint");sourceSummary=requiredText(summary,"sourceSummary");sourceDate=date;}
 public String getPlanId(){return planId;}public SourceType getSourceType(){return sourceType;}public String getSourceId(){return sourceId;}public String getSourceParentId(){return sourceParentId;}public long getSourceVersion(){return sourceVersion;}public String getSourceFingerprint(){return sourceFingerprint;}public String getSourceSummary(){return sourceSummary;}public LocalDate getSourceDate(){return sourceDate;}
}
